from pathlib import Path
import importlib.util
from collections import Counter

def transform(grid):
    occupied = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8}
    h, w = len(grid), len(grid[0])
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if box <= occupied:
                tiles.append((box, 1, (r,c), 'square'))
            # The missing corner determines the L's color.
            for missing, color in [((r,c), 2), ((r,c+1), 4), ((r+1,c), 3), ((r+1,c+1), 5)]:
                shape = box - {missing}
                if shape <= occupied:
                    tiles.append((shape, color, (r,c), 'L'))
    solutions = []
    def search(rem, chosen):
        if not rem:
            solutions.append(chosen)
            return
        cell = min(rem)
        for tile in tiles:
            shape = tile[0]
            if cell in shape and shape <= rem:
                search(rem - shape, chosen + [tile])
    search(occupied, [])
    if len(solutions) != 1:
        raise ValueError(f'Expected unique tile decomposition; got {len(solutions)}')
    out = [[0 for _ in row] for row in grid]
    for shape, color, _, _ in solutions[0]:
        for r,c in shape:
            out[r][c] = color
    return out

